(() => {
 'use strict';
 const $=s=>document.querySelector(s);
 const flow=items=>'<div class="teaching-flow">'+items.map((text,i)=>`<div><span>${i+1}</span>${text}</div>`).join('')+'</div>';
 const note=(title,text)=>`<div class="teaching-note"><b>${title}</b><p>${text}</p></div>`;
 const pair=(a,b)=>`<div class="concept-pair"><section>${a}</section><section>${b}</section></div>`;
 const lessons=[
 {short:'1978 年以前',unit:'01 · 改革開放以前',title:'先認識：共產主義、計畫經濟',goal:'分清楚制度背景、資源分配方式，以及當時的工業發展方向。',body:`<p>講義先以<strong>共產主義、計畫經濟</strong>介紹改革開放前的背景。這兩個詞相關，但不是同一個意思。</p>${pair('<h3>共產主義：思想與制度背景</h3><p>此處先掌握它重視公有的方向。講義用這個詞說明中國當時的制度背景。</p>','<h3>計畫經濟：怎麼安排生產？</h3><p>主要由國家規劃<strong>生產什麼、生產多少，以及資源如何分配</strong>，而不是主要由市場買賣來決定。</p>')}<h3>當時優先發展什麼？</h3><p>中國以<strong>軍事、重工業</strong>為重要發展方向。重工業通常需要大量能源、原料與大型設備，例如鋼鐵、機械等產業。</p>${flow(['國家規劃發展與資源分配','優先投入軍事、重工業','煤、鐵、石油提供能源與原料'])}<p>中國煤、鐵、石油等礦產多集中於<strong>北部地區</strong>，有利於傳統重工業發展。這是在說「資源條件支持工業」，不代表所有工業都只能位於北部。</p>${note('先記住這個起點','1978 年以前：以計畫經濟安排生產，偏重軍事與重工業。接下來的改革開放，會改變工業發展的方式。')}`,question:'「計畫經濟」主要指什麼？',options:['主要由國家規劃生產與資源分配','每間工廠只依國外訂單自行決定所有事情'],answer:0,explain:'計畫經濟是安排生產、分配資源的方式；軍事、重工業則是當時的重要發展方向。'},
 {short:'1978 年：改革開放',unit:'02 · 政策轉折',title:'1978 年起，實施經濟改革開放政策',goal:'理解「改革」與「開放」，再看工業發展方式如何改變。',body:`<p>1978 年是推動<strong>經濟改革開放</strong>的重要起點。不只要背年份，還要理解「發展方法」出現了什麼變化。</p>${pair('<h3>對內改革</h3><p>調整原有經濟運作方式，逐步引入市場機制。可以理解為：不再只用原本由國家統一規劃的方式安排所有經濟活動。</p>','<h3>對外開放</h3><p>增加對外經濟往來，吸引外國企業投資，帶進<strong>資金、技術與管理經驗</strong>，並發展外銷。</p>')}<h3>從「國家規劃」讀到「吸引外資」</h3><p>原本偏重軍事與重工業；改革開放後，東南沿海經濟特區逐漸發展紡織、製鞋等外銷產業。這是本課要觀察的工業發展變化。</p>${flow(['1978 年起：改革開放','吸引外國資金、技術與管理經驗','設廠生產，產品外銷','工商業發展，帶動經濟成長'])}${note('不是一夕之間全部改變','1978 年是政策轉折的起點，不代表所有工廠立即轉型，也不是所有經濟特區都在同一天成立。')}`,question:'「對外開放」如何幫助工業發展？',options:['完全停止與外國往來','吸引外資，帶入資金、技術與管理經驗'],answer:1,explain:'對外開放讓中國與外國企業、資金和市場的往來增加。下一段會解釋為什麼先從東南沿海開始。'},
 {short:'東南沿海與經濟特區',unit:'03 · 為什麼先從沿海開始？',title:'東南沿海如何吸引外資設廠？',goal:'把區位、優惠條件、工業類型與經濟成長連在一起。',body:`<p>改革開放初期，政策優先發展<strong>東南沿海都市</strong>。廈門、汕頭、深圳、珠海與海南等地，陸續設立以出口為導向的<strong>經濟特區</strong>。</p><p>經濟特區可先理解為：國家選定一些地區，提供特定優惠條件，吸引投資、發展對外經濟活動。這些地方不一定礦產最多，而是具備吸引外商的條件。</p><div class="three-reasons"><section><b>廉價勞力</b><p>較低工資有助降低生產成本。</p></section><section><b>交通便利</b><p>原料方便運入，產品方便外銷。</p></section><section><b>優惠政策</b><p>如優惠稅率，增加投資意願。</p></section></div><h3>為什麼常見紡織與製鞋？</h3><p>這些產業需要較多勞動人力，屬於<strong>勞力密集產業</strong>。勞力、交通與政策條件結合，有利外資設廠、將產品外銷。</p>${flow(['廉價勞力＋便利交通＋優惠政策','吸引外國企業設廠','發展紡織、製鞋等外銷產業','國內生產毛額提升，工商業成長'])}<figure class="teaching-figure"><button data-image="39" aria-label="放大課本第39頁經濟特區分布圖"><img src="learn-assets/textbook-39.png" alt="課本第39頁：經濟特區分布與產業轉型原頁" loading="lazy"></button><figcaption>找找看：東南沿海的五個經濟特區在哪裡？喀什又在哪裡？點圖可放大。</figcaption></figure>${note('再用上海理解交通條件','上海位於海岸線與長江水運交會處，又是鐵、公路運輸樞紐，因此成為工商業中心。交通可以連結原料、生產與市場。')}`,question:'早期沿海特區為什麼能吸引紡織、製鞋等工廠？',options:['勞力成本、對外運輸與優惠政策具有吸引力','因為這些地方完全不需要對外貿易'],answer:0,explain:'不只記住「沿海有工廠」，還要能解釋這些條件如何回應企業的生產、外銷需求。'},
 {short:'發展擴散與產業轉型',unit:'04 · 成長之後，方向也改變',title:'從沿海擴散，從勞力密集走向科技',goal:'分清楚「在哪裡發展」和「發展什麼產業」。',body:`<h3>第一個變化：發展範圍擴大</h3><p>經濟特區經驗擴大到<strong>東部沿海與長江沿岸都市</strong>，這些地方逐漸成為經濟發展核心。2010 年，新疆增設<strong>喀什經濟特區</strong>，借鏡東部發展經驗。</p><h3>第二個變化：部分都市產業轉型</h3><p>隨著發展，東部工資提高，原本靠低廉勞力競爭的優勢減弱。如果仍只依賴低工資，就不容易維持競爭力。因此部分都市轉向<strong>技術層級較高的科技或新創產業</strong>。</p>${flow(['早期：低成本勞力、加工與外銷','工資提高，低成本優勢減弱','提升技術、研發與產品價值','發展科技與新創產業'])}${pair('<h3>空間擴散：在哪裡？</h3><p>由特區擴大至東部沿海、長江沿岸；政策也延伸到西部的喀什。</p>','<h3>產業轉型：發展什麼？</h3><p>講義例子包含人工智慧、電動車、跨境電商與空中物流等。</p>')}${note('轉型不代表全部消失','部分都市轉型，不代表所有紡織、製鞋等傳統產業都消失。重點是發展重心與競爭方式改變。')}`,question:'東部工資提高後，產業升級有什麼作用？',options:['讓所有地方永遠只靠低工資競爭','提高技術與產品價值，回應成本及競爭的變化'],answer:1,explain:'升級不只是換一個產業名稱，而是提高技術層級，改變競爭方式。'},
 {short:'區域發展不均',unit:'05 · 成長帶來的新課題',title:'經濟成長了，為什麼各地仍有差距？',goal:'用政策先後、資金、技術與交通條件解釋區域差異。',body:`<p>改革開放帶動整體經濟成長，但<strong>整體成長不等於各地同樣成長</strong>。初期優先發展東南沿海，沿海較早得到投資與發展機會。</p><p>中、西部則有<strong>資金短缺、技術落後、對外交通不便</strong>等限制，發展程度較低。東部快速發展與都市擴張，也使城鄉、貧富差距更加明顯。</p>${flow(['政策初期優先發展東南沿海','中、西部有資金、技術與交通限制','東部發展程度高於中、西部','區域發展不均，差距擴大'])}<h3>為什麼不能全部用同一個策略？</h3><p>西部有資源但交通較弱；東北是老工業基地；東部則有升級需求。各地條件與問題不同，同一種做法不一定能回應真正的困難。</p><figure class="teaching-figure wide"><button data-map aria-label="放大四大經濟區課本原圖"><img src="learn-assets/regions-textbook.png" alt="課本第40頁四大經濟區分布與策略原圖" loading="lazy"></button><figcaption>先辨認西部、中部、東北、東部。接著依序學各區的「條件 → 困難 → 策略」。</figcaption></figure>${note('共同目標：均衡區域發展','均衡不是各地發展完全相同的產業，而是依不同條件制定策略，減緩區域差異。')}`,question:'四大經濟區為什麼需要不同的發展策略？',options:['各地優勢與限制不同，需要因地制宜','為了讓各地都成為完全相同的產業基地'],answer:0,explain:'先找出條件與問題，再判斷策略能否回應問題；這是後面四段的學習方法。'},
 {short:'西部：資源與交通',unit:'06 · 四大經濟區之一',title:'西部大開發：有資源，還需要把路打通',goal:'理解為什麼礦產豐富不一定會自動帶來經濟發展。',body:`<h3>優勢：礦產與能源豐富</h3><p>西部擁有礦產、能源，但資源若難以運往需要的地區，企業也不容易進入投資，資源優勢就不容易轉成經濟成果。</p><h3>困難：內陸位置與對外交通</h3><p>西部地處內陸，對外交通較不方便。解決方向不能只有「多開採」，還需要改善基礎設施、交通與投資環境。</p><h3>策略：西部大開發</h3><p>課本指出，1999 年提出西部大開發政策，強化基礎建設、改善投資環境，吸引國內外企業投資，也把資源輸往東部。</p>${flow(['資源豐富，但對外交通不便','改善交通、基礎建設與投資環境','企業較方便投資，資源較容易運出','發揮資源優勢，促進發展'])}${note('用西氣東輸理解區域分工','講義以西氣東輸為例：把西部天然氣輸往東部。西部供應能源，東部有使用需求；輸送設施連結不同地區。')}`,question:'哪個策略最直接回應西部的交通瓶頸？',options:['只要求各地都發展沿海港口','強化基礎建設，改善對外交通與投資環境'],answer:1,explain:'資源是優勢；改善交通與投資條件，才能幫助這項優勢發揮作用。'},
 {short:'中部：承東啟西',unit:'07 · 四大經濟區之二',title:'中部崛起：位置居中，連接東與西',goal:'把承東啟西讀成區位優勢，而不只是背四個字。',body:`<h3>位置：連結東部沿海與西部內陸</h3><p>中部相較東部較處內陸，發展程度較低；但位於東、西部之間，具有連結兩側的區位優勢。</p><h3>成本：工資較東部低</h3><p>工資會影響企業生產成本。中部工資相對較低，可作為吸引外資設廠的條件。</p><h3>策略：中部崛起</h3><p>課本指出，2004 年提出中部崛起政策，利用位置與工資優勢吸引投資，成為承「東」啟「西」的發展地區。</p>${flow(['位置居中＋工資較東部低','運用連結東、西的區位優勢','吸引外資設廠','推動中部地區發展'])}${note('承東啟西，不是全部搬家','重點是中部連結東、西部，不是「所有東部工廠都必須搬到中部」，也不是西部的能源輸送政策。')}`,question:'「位置居中、工資較低、承東啟西」對應哪項政策？',options:['中部崛起','振興東北'],answer:0,explain:'這些線索指向中部的區位與成本優勢；東北的重點則是老工業基地轉型。'},
 {short:'東北：老工業轉型',unit:'08 · 四大經濟區之三',title:'振興東北：從老工業基地尋找新方向',goal:'理解早期礦產豐富和後來礦產枯竭是不同階段。',body:`<h3>早期為什麼能發展？</h3><p>東北早期礦產資源豐富，形成重要的傳統重工業基地，呼應第一段學過的「礦產支持重工業」。</p><h3>後來遇到什麼困難？</h3><p>隨開發與時間推移，部分地區面臨<strong>礦產枯竭、工廠設備老舊</strong>。原本的發展條件改變，不能永遠依賴相同方式。</p><h3>策略：振興東北</h3><p>課本指出，2003 年提出振興東北政策，力求產業轉型。教材以<strong>傳統汽車業轉向電動車研發</strong>說明：利用工業基礎，朝新技術、新產品發展。</p>${flow(['早期礦產豐富，發展重工業','後來礦產枯竭、設備老舊','推動產業轉型、技術更新','尋找新的發展動力'])}${note('用時間順序解開疑惑','礦產豐富是早期基礎，礦產枯竭是後來問題。兩句並不矛盾，也正說明了為什麼需要轉型。')}`,question:'老工業基地面臨礦產枯竭與設備老舊，最符合哪個方向？',options:['只依賴原有礦產，不做調整','振興東北，推動產業轉型'],answer:1,explain:'東北策略回應的是老工業基地的困境；電動車研發例子的重點在產業轉型。'},
 {short:'東部：升級與新創',unit:'09 · 四大經濟區之四',title:'東部率先發展：從先發優勢走向升級',goal:'連結東部早期成功的條件，以及後來需要轉型的原因。',body:`<h3>為什麼東部成為經濟核心？</h3><p>東部對外開放較早，勞力充足、交通便利，加上政策優先發展，逐漸成為中國經濟發展核心。</p><h3>為什麼還要調整？</h3><p>發展後工資較高，勞力密集產業的低成本優勢減弱。這呼應前面的工業轉型：競爭不能永遠只靠便宜。</p><h3>策略：東部率先發展</h3><p>課本指出，2004 年提出東部率先發展政策，推動<strong>產業升級、新創產業</strong>，提高國際市場競爭力，並帶動其他地區。</p>${flow(['較早開放、交通便利，形成核心','工資提高，低成本優勢減弱','提升技術，發展新創產業','提高競爭力，帶動其他地區'])}${note('回頭連起整個單元','改革開放先讓沿海發展，之後出現轉型需求與區域差異。「東部升級」和「其他區域發展」要一起理解，不能只背政策名稱。')}`,question:'東部率先發展主要推動哪個方向？',options:['產業升級、新創產業，提高競爭力','放棄技術，只依賴更低工資'],answer:0,explain:'運用既有基礎提升競爭力，並帶動其他地區，不是要求各地複製同一種產業。'}
 ];

 const check=l=>({question:l.question,options:l.options,answer:l.answer,explain:l.explain});
 const original=lessons.slice();
 original[0].checks=[check(original[0]),{question:'1978 年以前，中國偏重發展哪些工業？',options:['軍事與重工業','以紡織、製鞋為主的外銷輕工業'],answer:0,explain:'1978 年以前偏重軍事與重工業；改革開放後，沿海特區才逐漸發展紡織、製鞋等外銷產業。'}];
 const coastal={...original[1],short:'改革開放與沿海特區',unit:'02 · 政策轉折與沿海發展',title:'改革開放後，為什麼先從東南沿海開始？',goal:'連起政策轉折、設廠條件、外銷產業與經濟成長。',body:original[1].body+'<h3>政策如何落實在沿海？</h3>'+original[2].body,checks:[check(original[1]),check(original[2])]};
 const regions=[
 {name:'西部',condition:'礦產、能源豐富',problem:'地處內陸，對外交通不便',policy:'西部大開發（1999）',strategy:'強化基礎建設、改善投資環境、吸引投資，資源輸往東部',example:'西氣東輸',lesson:original[5]},
 {name:'中部',condition:'位置連結東、西部，工資較東部低',problem:'較處內陸，發展不如東部',policy:'中部崛起（2004）',strategy:'利用區位與工資優勢，吸引外商設廠，承東啟西',example:'承「東」啟「西」',lesson:original[6]},
 {name:'東北',condition:'早期礦產豐富，具傳統重工業基礎',problem:'礦產逐漸枯竭、工廠設備老舊',policy:'振興東北（2003）',strategy:'推動產業轉型與技術更新',example:'傳統汽車業轉向電動車研發',lesson:original[7]},
 {name:'東部',condition:'開放早、勞力充足、交通便利',problem:'工資提高，低成本優勢減弱',policy:'東部率先發展（2004）',strategy:'產業升級、新創產業，提高國際競爭力並帶動其他區域',example:'科技、新創產業',lesson:original[8]}
 ];
 const regionTable=()=>'<div class="table-scroll region-table"><table><caption>四大經濟區：優勢 → 困難 → 策略</caption><thead><tr><th scope="col">地區</th><th scope="col">優勢</th><th scope="col">困難</th><th scope="col">政策與方向</th></tr></thead><tbody>'+regions.map(r=>'<tr><th scope="row">'+r.name+'</th><td>'+r.condition+'</td><td>'+r.problem+'</td><td><strong>'+r.policy+'</strong><br>'+r.strategy+'<br><small>例／關鍵詞：'+r.example+'</small></td></tr>').join('')+'</tbody></table></div>';
 const regionLesson={short:'四大經濟區比較與閃卡',unit:'05 · 四大經濟區一起看',title:'看地圖、比條件，再用閃卡記住策略',goal:'辨認四區位置，對照各區的優勢、困難與解決策略。',body:'<p>先在課本原圖找到西部、中部、東北、東部，再比較下表。每個策略都要回應當地的條件與問題。</p><figure class="teaching-figure wide"><button data-map aria-label="放大四大經濟區課本原圖"><img src="learn-assets/regions-textbook.png" alt="課本四大經濟區地圖：西部在西側，中部連接東西，東北在東北側，東部沿海；各區以不同邊界色標示"></button><figcaption>課本第40頁原圖，保留原有分區與資料年份；點圖可放大查看各區位置。</figcaption></figure>'+regionTable()+'<h3>想讀得更清楚？選一區回看講解</h3><div class="region-tabs" role="group" aria-label="選擇區域講解">'+regions.map((r,i)=>'<button data-region="'+i+'" aria-pressed="'+(i===0)+'">'+r.name+'</button>').join('')+'</div><section id="region-detail" aria-live="polite"></section><section class="flash-practice" aria-labelledby="flash-heading"><div class="eyebrow">先回想，再翻面</div><h3 id="flash-heading">四區閃卡練習</h3><p>看線索，先在心中說出地區或策略，再翻面確認。不計分，可反覆練習。</p><p id="flash-count"></p><div id="flash-card" aria-live="polite"></div><div class="flash-controls"><button id="flash-previous">← 上一張</button><button id="flash-flip" aria-pressed="false">翻面看答案</button><button id="flash-next">下一張 →</button></div><button id="flash-shuffle" class="quiet-guide">重新洗牌練習</button></section>',checks:regions.map(r=>check(r.lesson))};
 lessons.splice(0,lessons.length,original[0],coastal,{...original[3],unit:'03 · 成長之後，方向也改變'},{...original[4],unit:'04 · 成長帶來的新課題',explain:'先找出條件與問題，再判斷策略能否回應問題。下一段會用地圖與表格一起比較四區。'},regionLesson);
 const total=lessons.length;
 const flashcards=regions.flatMap(r=>[{front:r.condition+'；'+r.problem+'。這是哪一區？採取什麼策略？',back:r.name+'｜'+r.policy+'：'+r.strategy},{front:r.policy+'主要回應什麼條件或困難？',back:r.name+'：'+r.condition+'；'+r.problem+'。關鍵詞：'+r.example}]);
 function setupRegions(){if(!$('#region-detail'))return;const select=i=>{const r=regions[i];$('#region-detail').innerHTML='<h3>'+r.lesson.title+'</h3>'+r.lesson.body;document.querySelectorAll('[data-region]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.region)===i)));};document.querySelectorAll('[data-region]').forEach(b=>b.onclick=()=>select(Number(b.dataset.region)));select(0);let deck=flashcards.slice(),index=0,flipped=false;const show=()=>{$('#flash-count').textContent='第 '+(index+1)+' / '+deck.length+' 張';$('#flash-card').innerHTML='<b>'+(flipped?'答案':'線索')+'</b><p>'+(flipped?deck[index].back:deck[index].front)+'</p>';$('#flash-flip').textContent=flipped?'回到線索':'翻面看答案';$('#flash-flip').setAttribute('aria-pressed',String(flipped));$('#flash-previous').disabled=index===0;$('#flash-next').disabled=index===deck.length-1;};$('#flash-flip').onclick=()=>{flipped=!flipped;show();};$('#flash-next').onclick=()=>{if(index<deck.length-1){index++;flipped=false;show();}};$('#flash-previous').onclick=()=>{if(index>0){index--;flipped=false;show();}};$('#flash-shuffle').onclick=()=>{const prior=deck.slice();for(let i=deck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]];}if(deck.every((c,i)=>c===prior[i]))deck.push(deck.shift());index=0;flipped=false;show();};show();}

 const questions=i=>lessons[i].checks||[check(lessons[i])];
 let raw={};try{raw=JSON.parse(sessionStorage.getItem('geo34-guided-course-v4')||'{}')||{};}catch{}
 const state={index:0,solved:lessons.map((_,i)=>Array.isArray(raw.solved?.[i])?[...new Set(raw.solved[i].filter(n=>Number.isInteger(n)&&n>=0&&n<questions(i).length))]:[]),read:[]};
 const passed=i=>i<total&&state.solved[i].length===questions(i).length;
 const unlocked=()=>{let n=0;while(n<total&&passed(n))n++;return n;};
 state.index=Number.isInteger(raw.index)?Math.max(0,Math.min(raw.index,unlocked())):0;
 const save=()=>{state.read=lessons.map((_,i)=>i).filter(i=>i<unlocked());try{sessionStorage.setItem('geo34-guided-course-v4',JSON.stringify(state));}catch{}};
 function updateGate(){$('#progress').value=state.read.length;$('#progress-label').textContent='已通過 '+state.read.length+' / '+total+' 段講解';const done=state.index<total&&passed(state.index);$('#next').disabled=!done;$('#next').textContent=done?(state.index===total-1?'全部答對，整理全課 →':'全部答對，下一段 →'):'請先答對本段所有題目';document.querySelectorAll('[data-page]').forEach(b=>{b.disabled=Number(b.dataset.page)>unlocked();});const status=$('#gate-status');if(status)status.textContent='本段已答對 '+state.solved[state.index].length+' / '+questions(state.index).length+' 題'+(done?'，已解鎖下一段。':'，全部答對後可進入下一段。');}
 function openImage(src,title){$('#source-image').src=src;$('#source-title').textContent=title;$('#source-viewer').showModal();}
 function render(scroll=true){save();$('#progress').value=state.read.length;$('#progress-label').textContent='已通過 '+state.read.length+' / '+total+' 段講解';$('#course-nav').innerHTML=[...lessons.map(l=>l.short),'全課整理'].map((title,i)=>`<button data-page="${i}" ${i===state.index?'aria-current="step"':''}><span>${String(i+1).padStart(2,'0')}</span>${title}${state.read.includes(i)?'<b aria-label="已通過">✓</b>':''}</button>`).join('');document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{if(Number(b.dataset.page)<=unlocked()){state.index=Number(b.dataset.page);render();}});$('#previous').disabled=state.index===0;$('#next').hidden=state.index===total;$('#next').textContent=state.index===total-1?'我讀懂了，整理全課 →':'我讀懂了，下一段 →';
 if(state.index===total)renderSummary();else {const l=lessons[state.index];$('#lesson-content').innerHTML=`<div class="eyebrow">${l.unit}</div><p class="step-count">第 ${state.index+1} / ${total} 段講解</p><h2 tabindex="-1" id="lesson-heading">${l.title}</h2><div class="learning-goal"><b>這段要學會</b><p>${l.goal}</p></div><div class="teaching-copy">${l.body}</div><section class="understanding"><div class="eyebrow">讀完後，確認一下</div><p class="small">本段所有題目都答對後，才能進入下一段。答錯可以回讀講解、重新作答。</p><p id="gate-status" role="status"></p>${(l.checks||[check(l)]).map((q,n)=>`<div class="understanding-item"><h3>${n+1}. ${q.question}</h3><div class="understanding-options">${q.options.map((o,i)=>`<button data-check="${n}" data-option="${i}">${o}</button>`).join('')}</div><p id="feedback-${n}" role="status"></p><button data-reread="${n}" class="quiet-guide" hidden>↑ 回讀本段講解</button></div>`).join('')}</section>`;document.querySelectorAll('[data-check]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.check),q=(l.checks||[check(l)])[n],yes=Number(b.dataset.option)===q.answer;$('#feedback-'+n).textContent=(yes?'✓ 理解正確。':'再回想剛才的講解。')+q.explain;$('#feedback-'+n).className=yes?'answer-good':'answer-retry';document.querySelector('[data-reread="'+n+'"]').hidden=yes;if(yes&&!state.solved[state.index].includes(n)){state.solved[state.index].push(n);save();}if(yes)document.querySelectorAll('[data-check="'+n+'"]').forEach(o=>o.disabled=true);updateGate();});document.querySelectorAll('[data-reread]').forEach(b=>b.onclick=()=>$('#lesson-heading').scrollIntoView({block:'start',behavior:'smooth'}));setupRegions();state.solved[state.index].forEach(n=>{document.querySelectorAll('[data-check="'+n+'"]').forEach(o=>o.disabled=true);$('#feedback-'+n).textContent='✓ 已答對。'+questions(state.index)[n].explain;$('#feedback-'+n).className='answer-good';});}

 document.querySelectorAll('[data-image]').forEach(b=>b.onclick=()=>openImage('learn-assets/textbook-'+b.dataset.image+'.png','課本第 '+b.dataset.image+' 頁'));document.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>openImage('learn-assets/regions-textbook.png','課本第 40 頁 · 四大經濟區'));updateGate();if(scroll){$('#lesson-content').scrollIntoView({block:'start',behavior:'smooth'});$('#lesson-content h2')?.focus({preventScroll:true});}}
 function renderSummary(){$('#lesson-content').innerHTML=`<div class="eyebrow">06 · 把整個單元連起來</div><h2 tabindex="-1">從發展工業，到均衡區域發展</h2><p>現在試著說明這條路線，而不只是背答案。</p>${flow(['1978 年以前：計畫經濟，偏重軍事、重工業','1978 年起：改革開放，吸引外資與技術','東南沿海：運用勞力、交通、優惠政策發展外銷','部分都市升級，同時出現區域發展不均','依各地優勢與問題，制定四大經濟區策略'])}<h3>四區比較：策略要回應問題</h3><div class="table-scroll"><table><caption>條件 → 問題 → 策略</caption><thead><tr><th>地區</th><th>優勢與問題</th><th>政策與方向</th></tr></thead><tbody><tr><td>西部</td><td>資源豐富，但交通不便</td><td>西部大開發：基礎建設、投資環境、資源輸送</td></tr><tr><td>中部</td><td>位置居中，工資較低</td><td>中部崛起：承東啟西、吸引設廠</td></tr><tr><td>東北</td><td>老工業基地，礦產枯竭、設備老舊</td><td>振興東北：產業轉型</td></tr><tr><td>東部</td><td>開放早、交通好，但工資提高</td><td>東部率先發展：產業升級、新創</td></tr></tbody></table></div>${note('試著用自己的話說說看','① 改革開放如何改變工業發展？<br>② 為什麼整體成長，仍會有區域發展不均？<br>③ 為什麼四區不能全部採用同一種策略？')}<p>還說不清楚時，可以用目錄回讀。你已通過 ${state.read.length} / ${total} 段；閱讀完成不代表一定精熟，能解釋原因才是學習重點。</p><a class="primary guide-return" href="index.html">回到精熟練習 →</a>`;}
 $('#previous').onclick=()=>{if(state.index>0){state.index--;render();}};$('#next').onclick=()=>{if(state.index<total&&passed(state.index)){state.index++;render();}};document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>openImage('learn-assets/textbook-'+b.dataset.source+'.png','課本第 '+b.dataset.source+' 頁'));$('#close-source').onclick=()=>$('#source-viewer').close();render(false);
})();
